interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

contract TokenHelper {
    address public target;
    IUniswapV2Router02 public router;

    constructor(address _target) {
        target = _target;
        router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    }

    function buyTokens() external payable {
        // Buy tokens from the pair
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = target;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 0.1 ether
        }(
            0,
            path,
            address(this),
            block.timestamp
        );
    }

    function transferTokensToContract() external {
        // Transfer tokens to the contract to trigger swapAndLiquify
        uint256 balance = JizzJet(target).balanceOf(address(this));
        JizzJet(target).transfer(target, balance);
    }

    receive() external payable {}
}

